import { useState } from 'react'
import { Link } from 'react-router-dom'
import Wordmark from '../componentes/Wordmark.jsx'
import EstanteDaSemana from '../componentes/EstanteDaSemana.jsx'
import { estiloFase, CORES } from '../marca.js'

/**
 * Estudo: 5 alternativas para o cabeçalho da lista de ações (kicker + título + ritmo + progresso).
 * Rota /versoes-secao. Só para escolher; a escolhida vai para PlanoDaSemana.jsx.
 */
const OPCOES = [1, 2, 3, 4, 5]

function Kicker() { return <p className="text-[11px] font-extrabold uppercase tracking-[.16em] text-mudo mb-2">Constância vale mais que volume</p> }
function Titulo({ feitas, total, nome = 'Camila' }) {
  const t = total > 0 && feitas === total ? `Semana fechada, ${nome}.` : feitas === 0 ? `${nome}, vamos começar.` : `Boa, ${nome}. ${total - feitas === 1 ? 'Falta uma.' : `Faltam ${total - feitas}.`}`
  return <h2 className="display text-[26px] sm:text-[30px] text-balance">{t}</h2>
}
function Seletor({ total, onTotal, rotulo = 'Ações por semana', classe = '' }) {
  return (
    <div className={'flex flex-wrap items-center gap-3 text-[12.5px] text-apoio ' + classe} role="group" aria-label="Ações por semana">
      <span className="font-semibold">{rotulo}</span>
      <span className="inline-flex border-2 border-tinta">
        {OPCOES.map((n) => <button key={n} onClick={() => onTotal(n)} aria-pressed={total === n} className={'w-9 h-8 text-[13px] font-extrabold transition-colors ' + (total === n ? 'bg-tinta text-white' : 'bg-white text-tinta hover:bg-areia')}>{n}</button>)}
      </span>
    </div>
  )
}

/** 1. Placar: a fração grande fala sozinha; a estante vira apoio, sem frase. */
function V1({ feitas, total, onTotal }) {
  return (
    <div>
      <div className="flex flex-wrap items-end justify-between gap-4 pb-5">
        <div><Kicker /><Titulo feitas={feitas} total={total} /></div>
        <div className="text-right">
          <p className="display text-[44px] leading-none tabular-nums"><span className={feitas ? 'text-fase' : ''}>{feitas}</span><span className="text-fio">/</span>{total}</p>
          <div className="mt-1 flex justify-end"><EstanteDaSemana total={total} feitas={feitas} altura={22} /></div>
        </div>
      </div>
      <Seletor total={total} onTotal={onTotal} />
    </div>
  )
}

/** 2. Seletor-estante: escolher o ritmo e ver o progresso é o mesmo objeto. Cada número é uma lombada. */
function V2({ feitas, total, onTotal }) {
  return (
    <div>
      <div className="pb-5"><Kicker /><Titulo feitas={feitas} total={total} /></div>
      <div className="flex flex-wrap items-end gap-4" role="group" aria-label="Ações por semana">
        <span className="text-[12.5px] font-semibold text-apoio self-center">Ações por semana</span>
        <span className="inline-flex items-end gap-1.5">
          {OPCOES.map((n) => {
            const naSemana = n <= total, feita = n <= feitas
            const h = 34 + ((n * 7) % 12)
            return (
              <button key={n} onClick={() => onTotal(n)} aria-pressed={total === n} title={`${n} por semana`}
                className={'relative flex items-end justify-center pb-1.5 w-9 transition-all ' + (feita ? 'bg-fase text-white' : naSemana ? 'bg-white text-tinta' : 'bg-transparent text-mudo/50')}
                style={{ height: h + 10, borderRadius: '3px 3px 0 0', boxShadow: naSemana ? `inset 0 0 0 2px ${CORES.tinta}` : `inset 0 0 0 2px ${CORES.fio}` }}>
                <b className="absolute left-2 right-2 top-[6px] h-[2px]" style={{ background: feita ? 'rgba(255,255,255,.7)' : naSemana ? CORES.tinta : CORES.fio }} />
                <b className="absolute left-2 right-2 top-[10px] h-[2px]" style={{ background: feita ? 'rgba(255,255,255,.7)' : naSemana ? CORES.tinta : CORES.fio }} />
                <span className="text-[12px] font-extrabold leading-none">{n}</span>
              </button>
            )
          })}
        </span>
        <span className="text-[12.5px] text-apoio self-center">{feitas === 0 ? `${total} nesta semana` : `${feitas} de ${total} feitas`}</span>
      </div>
    </div>
  )
}

/** 3. Cartão preto: o progresso ganha um bloco próprio, no vocabulário do hero (preto + âmbar). */
function V3({ feitas, total, onTotal }) {
  return (
    <div className="grid grid-cols-1 md:grid-cols-[1fr_auto] gap-4 items-end">
      <div>
        <Kicker /><Titulo feitas={feitas} total={total} />
        <Seletor total={total} onTotal={onTotal} classe="mt-4" />
      </div>
      <div className="bg-tinta text-white px-5 py-4 corte-d min-w-[220px]">
        <p className="text-[10.5px] font-extrabold uppercase tracking-[.14em] text-ambar">Semana 39</p>
        <p className="display text-[26px] leading-none mt-1 tabular-nums">{feitas} <span className="text-white/50">de</span> {total}</p>
        <span role="img" aria-label={`${feitas} de ${total}`} className="mt-3 inline-flex items-end gap-1" style={{ height: 24 }}>
          {Array.from({ length: total }, (_, i) => (
            <i key={i} className="block relative" style={{ width: 12, height: `${70 + ((i * 23) % 30)}%`, borderRadius: '3px 3px 0 0', background: i < feitas ? CORES.ambar : 'transparent', boxShadow: i < feitas ? undefined : `inset 0 0 0 2px ${CORES.ambar}`, opacity: i < feitas ? 1 : .6 }}>
              <b className="absolute left-[3px] right-[3px] top-[5px] h-[2px]" style={{ background: i < feitas ? 'rgba(0,0,0,.45)' : CORES.ambar }} />
            </i>
          ))}
        </span>
      </div>
    </div>
  )
}

/** 4. Só palavras: sem gráfico. Uma frase de estado embaixo do título e o ritmo na mesma linha, à direita. */
function V4({ feitas, total, onTotal }) {
  const estado = feitas === 0 ? `${total} ${total === 1 ? 'ação' : 'ações'} nesta semana. Nenhuma feita ainda.` : feitas === total ? `${total} de ${total}. Semana completa.` : `${feitas} de ${total} feitas.`
  return (
    <div className="flex flex-wrap items-end justify-between gap-4">
      <div>
        <Kicker /><Titulo feitas={feitas} total={total} />
        <p className="text-[14px] text-apoio mt-2">{estado}</p>
      </div>
      <Seletor total={total} onTotal={onTotal} classe="pb-1" />
    </div>
  )
}

/** 5. Estante-título: a estante cresce e vira o ícone da seção, colada ao título; a fração vira etiqueta. */
function V5({ feitas, total, onTotal }) {
  return (
    <div>
      <div className="flex items-end gap-5 pb-5">
        <div className="bg-areia px-3 pt-3 pb-2 shrink-0"><EstanteDaSemana total={total} feitas={feitas} altura={52} /></div>
        <div className="min-w-0">
          <p className="text-[11px] font-extrabold uppercase tracking-[.16em] text-mudo mb-2">Constância vale mais que volume <span className="text-tinta ml-2 tabular-nums">· {feitas}/{total}</span></p>
          <Titulo feitas={feitas} total={total} />
        </div>
      </div>
      <Seletor total={total} onTotal={onTotal} />
    </div>
  )
}

const VERSOES = [
  { n: 1, nome: 'Placar', desc: 'A fração grande (0/3) à direita, estante pequena embaixo dela. Sem frase.', C: V1 },
  { n: 2, nome: 'Seletor-estante', desc: 'Os números 1 a 5 são lombadas: as escolhidas ficam em contorno, as feitas se preenchem. Um objeto só para ritmo e progresso.', C: V2 },
  { n: 3, nome: 'Cartão preto', desc: 'Um bloco preto com "Semana 39 · 0 de 3" e a estante em âmbar, no vocabulário do hero.', C: V3 },
  { n: 4, nome: 'Só palavras', desc: 'Sem gráfico. Uma frase de estado embaixo do título; o ritmo na mesma linha, à direita.', C: V4 },
  { n: 5, nome: 'Estante-título', desc: 'A estante cresce e vira o ícone da seção, colada ao título; a fração vira etiqueta no kicker.', C: V5 },
]

export default function SecaoVersoes() {
  const [feitas, setFeitas] = useState(0)
  const [total, setTotal] = useState(3)
  const f = Math.min(feitas, total)
  return (
    <div className="min-h-screen" style={estiloFase('construcao')}>
      <div className="border-b-2 border-tinta"><div className="max-w-4xl mx-auto px-4 sm:px-6 py-4 flex items-center justify-between"><Wordmark tamanho={24} /><Link to="/" className="btn-linha">← Área do autor</Link></div></div>
      <main className="max-w-4xl mx-auto px-4 sm:px-6 py-8">
        <h1 className="display text-[30px]">5 alternativas para o cabeçalho das ações</h1>
        <p className="text-[13.5px] text-apoio mt-2 max-w-[70ch]">Todas mantêm o kicker, o título por estado e o ritmo (1 a 5). O que muda é como o progresso aparece. Use os controles para simular.</p>
        <div className="mt-4 flex flex-wrap items-center gap-6 bg-areia px-5 py-3 text-[13px]">
          <span className="font-semibold">Simular:</span>
          <label className="flex items-center gap-2">feitas <input type="range" min="0" max={total} value={f} onChange={(e) => setFeitas(Number(e.target.value))} /> <b className="tabular-nums">{f}</b></label>
          <span className="text-mudo">ritmo: clique em qualquer seletor abaixo</span>
        </div>
        <div className="mt-10 grid gap-14">
          {VERSOES.map(({ n, nome, desc, C }) => (
            <section key={n} id={`v${n}`}>
              <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo mb-1"><span className="bg-tinta text-white px-1.5 py-0.5 mr-2">{n}</span>{nome}</p>
              <p className="text-[13px] text-apoio mb-5 max-w-[70ch]">{desc}</p>
              <div className="bg-white border-2 border-fio p-6 sm:p-8"><C feitas={f} total={total} onTotal={setTotal} /></div>
            </section>
          ))}
        </div>
      </main>
    </div>
  )
}
